-- transaksi pendaftaran KB
INSERT INTO transaksi (no_transaksi, nama_bank, user_email, user_name, user_phone, description, id_biaya_pendaftaran, total_biaya, status_transaksi, created_at, expired_datetime)
SELECT s.no_transaksi, 'BNI', s.email, s.nama_lengkap, '', CONCAT('Tagihan Pendaftaran KB a.n ', UPPER(s.nama_lengkap)), 9, 1000000, 0, s.created_at, DATE_ADD(s.created_at, INTERVAL 3 DAY)
FROM siswa_kb s WHERE s.email LIKE '%.seedkb@example.com'
AND NOT EXISTS (SELECT 1 FROM transaksi t WHERE t.no_transaksi = s.no_transaksi);

